contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(address actor, bytes memory data) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        SuccessCallee callee = new SuccessCallee();
        vm.prank(actor);
        bool ok;
        try c.forward(address(callee), data) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

